"""Generate the compact bilingual wiki from maintained content and approved templates."""
from pathlib import Path
import json
r=Path(__file__).resolve().parents[1];c=json.loads((r/'resources/content.json').read_text());w=r/'wiki';repo='https://github.com/deckerweb/purify-wpforms-lite'
for lang in ['en','de']:
 de=lang=='de';d=c[lang];home='Home-de' if de else 'Home';other='Home' if de else 'Home-de';start='Erste-Schritte' if de else 'Getting-started';guide='Anleitung' if de else 'User-guide';faq='Fragen-nach-Themen' if de else 'FAQ-by-topic';history='Aenderungsverlauf' if de else 'Changelog';help='Hilfe-und-Sicherheit' if de else 'Help-and-security'
 nav=('[English]('+other+')' if de else '[Deutsch]('+other+')')+' · [FAQ]('+faq+')'
 (w/(home+'.md')).write_text('# Purify WPForms Lite\n\n![Purify WPForms Lite]('+repo+'/raw/main/assets/github-banner-'+lang+'.png)\n\n'+('Mehr Fokus. Weniger Ablenkung.' if de else 'More focus. Less distraction.')+'\n\n'+d['intro']+'\n\n'+nav+'\n\n## '+('Dokumentation' if de else 'Documentation')+'\n\n'+'\n'.join('- ['+label+']('+target+')' for label,target in [('Erste Schritte' if de else 'Getting started',start),('Anleitung' if de else 'User guide',guide),('Fragen nach Themen' if de else 'FAQ by topic',faq),('Änderungsverlauf' if de else 'Changelog',history),('Hilfe und Sicherheit' if de else 'Help and security',help)])+'\n')
 (w/(start+'.md')).write_text('# '+('Erste Schritte' if de else 'Getting started')+'\n\n'+('[English](Getting-started)' if de else '[Deutsch](Erste-Schritte)')+'\n\n'+('WordPress 6.7 oder neuer und PHP 8.1 oder neuer sind erforderlich. Lade das Plugin-ZIP unter Plugins → Installieren → Plugin hochladen hoch und aktiviere es. Aktiviere WPForms Lite, wenn es noch fehlt. Prüfe den Status in der Pluginliste. Einträge, Einstellungen und Formulare bleiben erhalten.' if de else 'Requires WordPress 6.7 or newer and PHP 8.1 or newer. Upload the plugin ZIP under Plugins → Add New → Upload Plugin and activate it. Activate WPForms Lite if it is missing, then check the status in the plugin list. Entries, settings and forms are preserved.')+'\n')
 (w/(guide+'.md')).write_text('# '+('Anleitung' if de else 'User guide')+'\n\n'+('[English](User-guide)' if de else '[Deutsch](Anleitung)')+'\n\n'+'\n\n'.join(d['glance'])+'\n\n'+d['faq'][2][1]+'\n\n'+d['faq'][3][1]+'\n\n'+d['faq'][4][1]+'\n')
 (w/(history+'.md')).write_text('# '+('Änderungsverlauf' if de else 'Changelog')+'\n\n'+('[English](Changelog)' if de else '[Deutsch](Aenderungsverlauf)')+'\n\n'+'\n\n'.join('## '+v+' · '+date+'\n\n'+'\n'.join('- **'+p+':** '+t for p,t in items)for v,date,items in d['history'])+'\n')
 (w/(help+'.md')).write_text('# '+('Hilfe und Sicherheit' if de else 'Help and security')+'\n\n'+('[English](Help-and-security)' if de else '[Deutsch](Hilfe-und-Sicherheit)')+'\n\n[Issues]('+repo+'/issues) · [Discussions]('+repo+'/discussions)\n\n'+('Sicherheitslücken bitte vertraulich melden:' if de else 'Please report security vulnerabilities privately:')+' [Security policy]('+repo+'/security/policy) · [Private report]('+repo+'/security/advisories/new)\n')
 (w/(faq+'.md')).write_text((r/'docs'/('FAQ.'+lang+'.md')).read_text().replace('FAQ.en.md','FAQ-by-topic').replace('FAQ.de.md','Fragen-nach-Themen'))
(w/'_Sidebar.md').write_text('## English\n\n- [Home](Home)\n- [Getting started](Getting-started)\n- [User guide](User-guide)\n- [FAQ by topic](FAQ-by-topic)\n- [Changelog](Changelog)\n- [Help and security](Help-and-security)\n\n## Deutsch\n\n- [Startseite](Home-de)\n- [Erste Schritte](Erste-Schritte)\n- [Anleitung](Anleitung)\n- [Fragen nach Themen](Fragen-nach-Themen)\n- [Änderungsverlauf](Aenderungsverlauf)\n- [Hilfe und Sicherheit](Hilfe-und-Sicherheit)\n')
(w/'_Footer.md').write_text('**Purify WPForms Lite · Documentation / Dokumentation**\n\n[Wiki home / Wiki-Startseite]('+repo+'/wiki) · [Repository]('+repo+') · [Downloads & Releases]('+repo+'/releases)\n\n[Help & bugs / Hilfe & Fehler]('+repo+'/issues) · [Discussions / Austausch]('+repo+'/discussions) · [Security / Sicherheit]('+repo+'/security/policy)\n\n© 2022–2026 David Decker – DECKERWEB.  \nPlugin license / Plugin-Lizenz: [GPL v2 or later / GPL v2 oder höher](https://www.gnu.org/licenses/gpl-2.0.html).\n')
